import type * as SarvamAI from "../../../../index.js";
/**
 * @example
 *     {
 *         lang: "hi-IN"
 *     }
 */
export interface DocumentTranslationTriggerExportRequest {
    /** BCP-47 target language code (e.g. `hi-IN`). */
    lang: SarvamAI.DocumentLanguage;
    /**
     * Optional target export format. When omitted, defaults to the uploaded file's native format.
     *
     * - **PDF uploads:** may be set to `pdf` (default), `docx`, `html`, `txt`, or `epub`.
     * - **Microsoft Office uploads** (`.doc`, `.docx`, `.xls`, `.xlsx`, `.ppt`, `.pptx`, and related formats): always export in the original format only; other values are rejected.
     */
    format?: SarvamAI.ExportFormat;
    /** When true, the export may reduce line spacing to fit translated text within the original layout. PDF/DOCX only. */
    fit_line_height?: boolean;
    /** When true, the export may reduce font size to fit translated text within the original layout. PDF/DOCX only. */
    fit_font_shrink?: boolean;
}
